CREATE TYPE "Role" AS ENUM ('ADMIN', 'STAFF');
CREATE TYPE "PCStatus" AS ENUM ('ONLINE', 'OFFLINE', 'MAINTENANCE');
CREATE TYPE "Severity" AS ENUM ('INFO', 'WARNING', 'CRITICAL');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "password" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'STAFF', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Lab" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "location" TEXT NOT NULL, "capacity" INTEGER NOT NULL, "description" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Lab_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PC" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "ipAddress" TEXT NOT NULL, "macAddress" TEXT NOT NULL, "status" "PCStatus" NOT NULL DEFAULT 'OFFLINE', "lastSeen" TIMESTAMP(3), "notes" TEXT, "password" TEXT, "labId" TEXT NOT NULL, "manufacturer" TEXT, "model" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PC_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Alert" ("id" TEXT NOT NULL, "type" TEXT NOT NULL, "message" TEXT NOT NULL, "severity" "Severity" NOT NULL DEFAULT 'INFO', "isRead" BOOLEAN NOT NULL DEFAULT false, "pcId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Alert_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StatusLog" ("id" TEXT NOT NULL, "pcId" TEXT NOT NULL, "oldStatus" "PCStatus" NOT NULL, "newStatus" "PCStatus" NOT NULL, "changedBy" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StatusLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Setting" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "value" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Setting_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Setting_key_key" ON "Setting"("key"); CREATE INDEX "PC_labId_status_idx" ON "PC"("labId", "status"); CREATE INDEX "Alert_isRead_createdAt_idx" ON "Alert"("isRead", "createdAt");
ALTER TABLE "PC" ADD CONSTRAINT "PC_labId_fkey" FOREIGN KEY ("labId") REFERENCES "Lab"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Alert" ADD CONSTRAINT "Alert_pcId_fkey" FOREIGN KEY ("pcId") REFERENCES "PC"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "StatusLog" ADD CONSTRAINT "StatusLog_pcId_fkey" FOREIGN KEY ("pcId") REFERENCES "PC"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "StatusLog" ADD CONSTRAINT "StatusLog_changedBy_fkey" FOREIGN KEY ("changedBy") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
